import {createCardPrices} from './card-prices.mjs';
const node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
export function filterAgents(agents,team='',query=''){const q=query.trim().toLocaleLowerCase();return agents.filter(a=>(!team||a.team===team)&&(!q||[a.name,a.squad,a.collection].join(' ').toLocaleLowerCase().includes(q)))}
export function createAgentCatalog(root,{agents,onEquip}){
 const prices=createCardPrices(root);let team='';
 function render(){const matches=filterAgents(agents(),team,root.querySelector('#agentCatalogSearch').value),grid=root.querySelector('#agentCatalogGroups');grid.replaceChildren();root.querySelector('#agentCatalogCount').textContent=matches.length+' agentes';
  for(const side of ['CT','T']){const list=matches.filter(a=>a.team===side);if(!list.length)continue;const section=node('section','agent-catalog-group'),title=node('h3','',side==='CT'?'CT · Antiterroristas':'TT · Terroristas'),cards=node('div','agent-catalog-grid');title.append(node('span','',String(list.length)));section.append(title,cards);
   for(const agent of list){const card=node('article','agent-catalog-card'),image=node('img');image.src=agent.fullImage||agent.image;image.alt=agent.name+' · '+agent.squad;image.loading='lazy';image.decoding='async';const media=node('div','agent-catalog-media');media.append(image);const info=node('div','agent-catalog-info');info.append(node('small','',agent.squad),node('h4','',agent.name),node('p','',agent.collection));const market=node('div','card-market-prices');market.dataset.priceSkin=agent.id;market.dataset.priceWear='';market.dataset.priceVariant='normal';market.innerHTML='<small class="card-price-condition">Sin desgaste · USD</small><table class="card-price-table"><thead><tr><th>Estado</th><th>Steam</th><th>CSFloat</th></tr></thead><tbody class="card-wear-prices"><tr><td colspan="3">Consultando mercados…</td></tr></tbody></table>';const actions=node('div','agent-catalog-actions');for(const mode of ['current','desired']){const b=node('button',mode==='desired'?'primary':'',mode==='current'?'✓ Lo tengo':'♡ Lo quiero');b.onclick=()=>onEquip(agent,mode);actions.append(b)}card.append(media,info,market,actions);cards.append(card)}grid.append(section)
  }if(!matches.length)grid.append(node('p','catalog-empty','No hay agentes con esos filtros.'));prices.observe();
 }
 root.querySelector('#agentCatalogSearch').oninput=render;root.querySelectorAll('[data-agent-team]').forEach(b=>b.onclick=()=>{team=b.dataset.agentTeam;root.querySelectorAll('[data-agent-team]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});return{render};
}
